CREATE TABLE q(k INT, v INT);
INSERT INTO q VALUES (2, 2), (2, 0);
WITH RECURSIVE c(k) AS (SELECT 0 UNION ALL SELECT k + 1 FROM c WHERE k < 3), d AS (SELECT k FROM c) SELECT q.k, c.k FROM q, c WHERE (SELECT count(*) FROM d) = 4;
WITH RECURSIVE c(k) AS (SELECT 0 UNION ALL SELECT k + 1 FROM c WHERE k < 3), d AS (SELECT k FROM c) SELECT q.k FROM q WHERE (SELECT count(*) FROM c WHERE (SELECT max(k) FROM d) = 3) = 4;
WITH RECURSIVE c(k) AS (SELECT 0 UNION ALL SELECT k + 1 FROM c WHERE k < 3), d AS (SELECT k FROM c) SELECT c.k FROM c WHERE (SELECT count(*) FROM d) = 4;
EXPLAIN WITH RECURSIVE c(k) AS (SELECT 0 UNION ALL SELECT k + 1 FROM c WHERE k < 3), d AS (SELECT k FROM c) SELECT c.k FROM c WHERE (SELECT count(*) FROM d) = 4;
